import os, glob, re, json

def load_all_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        print("No session dir")
        return
    fpath = os.path.join(os.path.dirname(d), '..', '..', 'sessions', os.path.basename(d) + '.jsonl')
    fpath = os.path.normpath(fpath)
    try:
        with open(fpath, 'r') as f:
            content = f.read()
    except:
        print(f"File not found: {fpath}")
        return
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_all_grids()
print("Loaded grids:", list(G.keys()))
if 'Test input' in G:
    h, w = len(G['Test input']), len(G['Test input'][0])
    print(f"Test input shape: {h}x{w}")

